tAlign":null},"content":[{"text":"111,073","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"674,235","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Total equity","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"14,178,555","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(2,107,546)","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(47,332)","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"3,083,675","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"15,107,352","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Every row and column reconciles. Share capital has not moved since at least the end of 2022; APIC moved only by 7 in 2023.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"What Note 31 says.","type":"text","marks":[{"type":"bold"}]},{"text":" APIC \"represent[s] the difference between the purchase consideration and the carrying value from business combination transaction of entities under common control\" (Note 31, Daftar 5/146, PDF p. 163), and the policy applies pooling of interests with the difference in APIC (Note 3d, Daftar 5/37, PDF p. 54). It gives no transactions, dates or amounts. The likely source is the subholding restructuring. Pertamina designated PHE as parent of the Upstream Subholding in June 2020 (Note 1a, Daftar 5/2, PDF p. 19), and by a circular shareholders' resolution of 1 September 2021 PHE took over the shares Pertamina held in its upstream subsidiaries, eleven according to PHE's own publications, including, by one press list, Elnusa, whose 41.1 percent moved that day; PHE bought a further 9.99 percent from Dana Pensiun Pertamina in December 2021, reaching the 51.10 percent in Note 1b. PHE does not disclose the consideration. Shares issued at a nominal value above the transferred carrying amounts, or cash above them, would both produce the negative balance; the §7 mechanism is an inference from Notes 31 and 3d, not a disclosed fact.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Book value per share and legal headroom.","type":"text","marks":[{"type":"bold"}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Book value per share = 14,433,117 thousand / 396,225,242,340 = USD 0.0364","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Share capital per share at historical rates = 13,631,466 thousand / 396,225,242,340 = USD 0.0344","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Equity per share is only 6 percent above what the shares were paid in at, the same squeeze section 6 described.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The other equity component.","type":"text","marks":[{"type":"bold"}]},{"text":" PHE gives no note. The statement of changes in equity labels every movement \"Equity adjustment in subsidiaries\": −23,459 in 2023, with no effect on NCI, and +6,140 in 2024, in the same row as −53,470 against NCI. The consolidation policy treats changes in ownership of a subsidiary without loss of control as equity transactions (Note 3c, Daftar 5/34, PDF p. 51), which fits the label, but no transaction behind the 2024 row is disclosed. The Non-controlling interest essay analyses that movement.","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"11. Related lines","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"additional-paid-in-capital","type":"text","marks":[{"type":"code"}]},{"text":": share premium and common-control differences, covered on this page.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"other-equity-component","type":"text","marks":[{"type":"code"}]},{"text":": equity adjustments in subsidiaries, covered on this page.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"retained-earnings","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/retained-earnings","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": dividends, the statutory reserve and the reserve transfer in the table above.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"other-comprehensive-income","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/other-comprehensive-income","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the accumulated OCI of 103,851.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"non-controlling-interest","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/non-controlling-interest","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the 674,235 and the 53,470 adjustment.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"long-term-investments","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/long-term-investments","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":" and ","type":"text"},{"text":"intangible-assets-net","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/intangible-assets-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": investments in associates and goodwill from acquisitions that are not under common control.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3,"textAlign":null},"content":[{"text":"Least-confident assertions","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"That PHE's APIC arose mainly from the 2021 subholding restructuring is inferred. Note 31 gives only the definition, the FS cover 2023–2024, and the transfer of eleven subsidiaries and Elnusa comes from PHE publications and press reports, not the audited statements. UU PT does not force a negative difference: nominal value may be set anywhere up to the contribution's fair value, so the negative balance reflects a consideration (shares or cash) the parties set above the transferred carrying amounts.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The reading that UU PT bars issuing shares below nominal rests on art. 33 (full payment of issued capital) and DSAK IAI's Basis for Conclusions DK10, not on an article that says so in terms.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The buyback net-asset test is not run for PHE. The law states capital in rupiah and tests the company's own net assets; PHE publishes neither separate statements nor a precise year-end rate. Translated at a year-end rate the rupiah value of USD net assets has risen since 2021 while rupiah capital is fixed, so a USD comparison at historical rates would mislead. Note 33's Indonesian title (\"SALDO CADANGAN WAJIB\") treats the whole appropriation as the mandatory reserve, while the statement of changes in equity adds \"general and investment reserve\".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The reading of the other equity component as equity transactions in subsidiaries rests on its label and Note 3c. PHE does not describe it, which falls short of PSAK 201's request to describe each reserve. The 2024 investing receipt of 64,578 and Note 42's gain of 34,242 on sale of subsidiaries more likely relate to TPDC's January 2024 exercise of its call option over the Mnazi Bay interest (Note 5g) than to this row; PHE does not connect them, and a sale to an outsider would not reduce NCI.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PHE inconsistencies not used in the body: APIC, which Note 31 defines as common-control differences only, moved by 7 in 2023 in the \"equity adjustment in subsidiaries\" row; Note 32 describes issued capital as 25 percent of authorised capital where it is 25.08 percent.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"References","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PT Pertamina Hulu Energi dan Entitas Anak, consolidated financial statements 31 December 2024 (audited, USD thousand): statement of financial position, equity (Daftar 1/3, PDF p. 13); statement of profit or loss and OCI (Daftar 2/2, PDF p. 15); statement of changes in equity (Daftar 3, PDF p. 16); Note 1a–1b (Daftar 5/1–5/4, PDF pp. 18–21); Note 3c (Daftar 5/34, PDF p. 51); Note 3d (Daftar 5/37, PDF p. 54); Note 3r (Daftar 5/66, PDF p. 83); Note 31 (Daftar 5/146, PDF p. 163); Note 32 (Daftar 5/147, PDF p. 164); Note 33 (Daftar 5/147, PDF p. 164). VERIFIED (PHE FS 2024, on disk). Note 52 (subsequent events) contains no equity transactions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes this series follows, \"Inter 1 – Chapter 13 – Corporation: Organization and Capital Stock\" (Rumpun Akuntansi Keuangan; chapter title from Weygandt, ","type":"text"},{"text":"Accounting Principles","type":"text","marks":[{"type":"italic"}]},{"text":"): ordinary and preferred stock, par, no-par and stated value, authorised and issued, issue above and below par, issue for cash, non-cash assets and services, treasury stock under the cost method. NOTES. Corrections made here: the \"issued below value\" entry has no Indonesian counterpart; the treasury example (\"reissued 800 treasury stock market value $25 … Cash $2,000\") is a factor of ten too small (800 × 25 = 20,000), as are the later cases; authorisation is set in the articles and approved by the Minister of Law, not by \"persetujuan dari lembaga keuangan\".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes, \"Inter 2 – Chapter 15 – Equity\" (Rumpun Akuntansi Keuangan, following Kieso IFRS edition): corporate law, shareholder rights, components of equity, par and no-par shares, lump-sum sales, non-cash issues, issue costs, preference share features, treasury shares, presentation and analysis. NOTES. Corrections made here: the third patent case splits share capital and premium the wrong way round (25,000 / 100,000 for 100,000 / 25,000); dividend arrears on cumulative preference shares are not a liability until declared; preference shares that must be redeemed are liabilities under PSAK 232; \"tidak memiliki hak suara dalam RUPS\" is a common feature, not a rule (UU PT art. 53(4)(a)). Common-control restructurings and section 9 have no note.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"UU No. 40 Tahun 2007 tentang Perseroan Terbatas, arts. 31–38, 40, 49, 52–53, 70 and elucidations to arts. 8(2)(c), 32(2), 33(2)–(3), 34. VERIFIED (web, JDIH BPK, peraturan.bpk.go.id, original text; status page lists amendments by UU 11/2020, Perppu 2/2022 and UU 6/2023). Amended art. 32: VERIFIED (web, secondary: Hukumonline, \"Modal PT\", 18 January 2024, citing art. 109 point 3 Perppu 2/2022 and PP 8/2021); the amending text itself not opened. PP 8/2021 art. 5 (sector minimums): VERIFIED (web, secondary: Hukumonline).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 338 ","type":"text"},{"text":"Kombinasi Bisnis Entitas Sepengendali","type":"text","marks":[{"type":"italic"}]},{"text":" (formerly PSAK 38): renumbering VERIFIED (web, IAI renumbering list). Paras. 07–12, 14–15, 17–20 and DK08–DK14 of the 2012 text, and DK19–DK23A, VERIFIED (web, IAI, exposure draft PSAK 338 (Revisi 2025), which shows the 2012 text with tracked changes). Measurement at the transferred entity's carrying amounts VERIFIED (web, IAI, Discussion Paper PIR PSAK 338, 2024, paras. 19, 30–34, 36–41). 2025 revision approved 29 October 2025, effective 1 January 2026: VERIFIED (web, IAI, ","type":"text"},{"text":"DSAK Terkini","type":"text","marks":[{"type":"italic"}]},{"text":" vol. 7, 2025); final text not opened, so paragraph numbers are the exposure draft's.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 232 (IAS 32), paras. 18(a), 33, 35A, 37; PSAK 201 (IAS 1) equity disclosures; PSAK 103 (IFRS 3) para. 02(c) scope exclusion VERIFIED (web, quoted in IAI Discussion Paper PIR PSAK 338, footnote 1); PSAK 110 (IFRS 10); PSAK 102 (IFRS 2); PSAK 221 (IAS 21) on historical rates for equity: numbers VERIFIED (web, IAI renumbering list); content STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"POJK 12/POJK.03/2020 on bank consolidation, minimum core capital Rp3 trillion by 31 December 2022: VERIFIED (web, secondary: Kontan; Bisnis.com, 2020–2022). POJK 23/2023 insurance minimum equity: VERIFIED (web, secondary: Hukumonline) for its existence only. PP 6/2018 on Pertamina's state equity and PGN Series B shares: VERIFIED (web, secondary: Kontan, Hukumonline, Katadata, March–April 2018).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PHE subholding formation (circular resolution of 1 September 2021, eleven subsidiaries) and the Elnusa transfer: VERIFIED (web, secondary: PHE Sustainability Report 2021 and company profile as quoted in search results; CNBC Indonesia, 6 September 2021). Further 9.99 percent from Dana Pensiun Pertamina, December 2021: VERIFIED (web, secondary: Kontan; Bisnis, 3 December 2021). Note 5g (Daftar 5/88, PDF p. 105), Note 42 (Daftar 5/150, PDF p. 167) and the cash flow statement (Daftar 4, PDF p. 17) read for the other equity component. PHE's own pages could not be opened directly.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Kieso, Weygandt and Warfield, ","type":"text"},{"text":"Intermediate Accounting","type":"text","marks":[{"type":"italic"}]},{"text":", IFRS edition, ch. 15, the textbook the Inter 2 notes summarise. Not on disk; NOT VERIFIED.","type":"text"}]}]}]}]}$j$::jsonb,
       presentation = $p${"deck":"The theory of contributed capital from authorised shares to pooling of interests, worked through PHE's Rp198 trillion of issued capital and its negative additional paid-in capital, and set beside the industries with capital rules of their own","genre":null,"author_bio":null,"references":[],"hero_caption":null,"key_takeaways":["Equity is a residual, but company law carves out a fixed slice, legal capital, equal to the nominal value of issued shares, which in Indonesia must be paid in full and, for at least 25 percent of authorised capital, at incorporation. Anything paid above nominal is share premium (agio), shown with other contributions as additional paid-in capital.","Shares issued for cash are recorded at what is received less issue costs; shares issued for non-cash assets at the fair value of what is received, or of the shares if that is more reliable. Treasury shares and preference shares sit at the border with liabilities. A buyback is deducted from equity and never produces a gain or loss in profit, while a preference share the issuer must redeem is a liability whose dividends are interest.","When businesses move between companies under one controlling party, PSAK 338 replaces fair values with carrying amounts (pooling of interests) and books the difference from the consideration in additional paid-in capital. That difference is negative whenever the consideration exceeds the carrying amount taken over."],"revision_note":null}$p$::jsonb,
       updated_at = now()
 WHERE id = '7dbd6dc0-0e0a-43c3-92ab-b41c2fc36c3b';
INSERT INTO public.essay_revisions (essay_id, revision_no, change_type, title, snippet, content_json, status, change_summary, changed_by)
SELECT e.id, coalesce((SELECT max(x.revision_no) FROM public.essay_revisions x WHERE x.essay_id = e.id), 0) + 1, 'rollback',
       e.title, e.snippet, e.content_json, e.status, $s$Restored from the snapshot taken before the lecture-notes removal$s$, null
  FROM public.essays e WHERE e.id = '7dbd6dc0-0e0a-43c3-92ab-b41c2fc36c3b';

DO $chk$ BEGIN
  IF (SELECT count(*) FROM public.essays WHERE id IN ('d29a13f3-0f60-4efe-b744-172af36d2d62', '7f56ddf3-eb7b-4ec4-9216-919e7b1b853c', 'a295ed2d-9b80-47b0-88a6-b992b49c21b9', '7dbd6dc0-0e0a-43c3-92ab-b41c2fc36c3b') AND updated_at = now()) <> 4 THEN
    RAISE EXCEPTION 'Not written: an essay in this part was changed after the snapshot. Nothing in this part was saved.';
  END IF;
END $chk$;
COMMIT;
